DLLM17.raw_latex:
\begin{definition}\label{DefiQuantumRel}
Let  $\mathcal M$ be a von Neumann algebra and consider $\mathcal{P=\Proj(\mathcal M\bar{\otimes}\mathcal{B(\ell_2))$ endowed with the restriction of the weak operator topology.  An   open subset $\mathcal{R\subset \mathcal{P\times \mathcal{P$  is called an \emph{intrinsic quantum relation on $\mathcal M$} if the following hold.
\begin{enumerate}
\item\label{ItemDefiQuantumRel1} $(0,0)\not\in \mathcal{R$.
\item\label{ItemDefiQuantumRel2} Given  families of nonzero projections $(p_i)_{i\in I}$ and $(q_j)_{j\in J}$ in $\mathcal{P$, we have  
\[\Big(\bigvee_{i\in I} p_i, \bigvee_{j\in J} q_j\Big)\in \mathcal{R\ \iff \ \exists (i,j)\in I\times J\ \text{ with }\ (p_i,q_j)\in \mathcal{R.\]
\item \label{ItemDefiQuantumRel3} For all projections $p,q\in \mathcal{P$ and all $b\in 1_{\mathcal M}\otimes \mathcal{B(\ell_2)$, we have 
\[(p,[bq])\in \mathcal{R\ \iff\ ([b^*p],q)\in \mathcal{R.\]
Here square brackets
denote range projection.
\end{enumerate}
  We denote the set of all  intrinsic quantum relations on $\mathcal M$  by $\mathrm{IQRel}(\mathcal M)$.
\end{definition}

